
import type { CapabilityRequirements } from './CapabilityRequirements.js';
import type { MoneyMovementBlockedReason } from './MoneyMovementBlockedReason.js';
import type { NextAction } from './NextAction.js';

/** Merchant capability readiness for a payment or money movement capability. */ export type Capability = { /** Reasons this capability is blocked, pending, or not available. */ "blocked_reasons"?: Array<MoneyMovementBlockedReason>; /** Flint-owned capability name. Payment capabilities describe transaction acceptance readiness; money movement capabilities describe payout and balance movement readiness. */ "capability": "accept_card_payments" | "save_payment_methods" | "accept_affirm_payments" | "receive_payouts" | "create_standard_payouts" | "manage_payout_destinations" | "manage_payout_settings" | (string & {}); /** Capability domain. API keys scoped to one domain only receive that domain when listing capabilities without a domain filter. */ "domain": "money_movement" | "payments" | (string & {}); /** Actions that can remediate or refresh this capability when Flint can suggest one. */ "next_actions"?: Array<NextAction>; /** RFC3339 timestamp for the source state used to evaluate this capability. Format: date-time. */ "observed_at"?: string; /** Merchant requirements that affect this capability. */ "requirements": CapabilityRequirements; /** Current readiness status for this capability. */ "status": "ready" | "blocked" | "pending" | "not_available" | (string & {}); };
